/* @lc app=leetcode id=3966 lang=kotlin */ class Solution { fun cnt(N: Long, k: Int): Long = (2..16).fold(listOf(LongArray(10) { 1L })) { acc, _ -> acc + LongArray(10) { d -> (0..9).filter { Math.abs(d - it) <= k }.sumOf { acc.last()[it] } } }.let { W -> N.toString().map { it - '0' }.let { ds -> (1 until ds.size).sumOf { L -> (1..9).sumOf { W[L - 1][it] } } + ds.indices.fold(true to 0L) { (alive, tot), i -> if (!alive) alive to tot else (if (i == 0) 1 else 0).until(ds[i]).filter { c -> i == 0 || Math.abs(c - ds[i - 1]) <= k }.sumOf { W[ds.size - i - 1][it] }.let { add -> ((i == 0 || Math.abs(ds[i] - ds[i - 1]) <= k) to tot + add) } }.let { (alive, tot) -> tot + (if (alive) 1 else 0) } } } fun goodIntegers(l: Long, r: Long, k: Int): Long = cnt(r, k) - cnt(l - 1, k) }